# ---------- WRITE ----------
by_subj = collections.defaultdict(list)
for r in Q:
    by_subj[r[0]].append(r)
total = 0
for subj, rows in sorted(by_subj.items()):
    path = OUT / f"{subj}.csv"
    with open(path, "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f)
        w.writerow(["qid","question","option_a","option_b","option_c","option_d","option_e","correct_answer","explanation","topic","subtopic","difficulty","source"])
        import random as _rnd
        for i, r in enumerate(rows, 1):
            _, q,a,b,c,d,ans,expl,topic,sub,diff = r
            opts = [a,b,c,d]; correct = opts["ABCD".index(ans)]
            rng = _rnd.Random(f"{subj}-{i}")
            rng.shuffle(opts)
            new_ans = "ABCD"[opts.index(correct)]
            w.writerow([f"{subj.upper()}-{i:03d}", q, opts[0],opts[1],opts[2],opts[3], E_TXT, new_ans, expl, topic, sub, diff, "Generated — syllabus-based"])
    total += len(rows)
    print(subj, len(rows), "->", path.name)
print("TOTAL", total)
